create extension if not exists pgcrypto;
create extension if not exists vector;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create table if not exists public.companies (id uuid primary key default gen_random_uuid(), name text not null, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, company_id uuid references public.companies(id) on delete set null, full_name text, phone text, role text not null default 'applicant' check (role in ('admin','recruiter','viewer','employer','evaluator','applicant')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.candidates (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, user_id uuid references auth.users(id) on delete set null, full_name text not null, email text, phone text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists candidates_company_user_uidx on public.candidates(company_id, user_id) where user_id is not null;
create table if not exists public.jobs (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, title text not null, description text not null default '', location text, is_remote boolean not null default false, employment_type text, status text not null default 'draft' check (status in ('draft','open','closed')), jd_parsed_json jsonb, requirements_generated_at timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.job_requirements (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs(id) on delete cascade, req_type text not null, req_value text not null, weight numeric(8,3) not null default 1, must_have boolean not null default false, source text not null default 'manual' check (source in ('manual','auto')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.candidate_resumes (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, candidate_id uuid not null references public.candidates(id) on delete cascade, file_name text, mime_type text, storage_path text, status text not null default 'queued' check (status in ('queued','processing','done','failed','uploaded')), stage text not null default 'submitted' check (stage in ('submitted','analyzed','screening','shortlisted','interview','offer','hired','rejected')), text_extracted text, parsed_json jsonb, last_error text, retention_until timestamptz not null default (now() + interval '30 days'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.candidate_scores (candidate_resume_id uuid primary key references public.candidate_resumes(id) on delete cascade, raw_score numeric(8,5), penalty numeric(8,5), final_score numeric(8,5), warnings jsonb, breakdown jsonb, updated_at timestamptz not null default now());
create table if not exists public.job_embeddings (job_id uuid primary key references public.jobs(id) on delete cascade, embedding vector(384) not null, updated_at timestamptz not null default now());
create table if not exists public.candidate_resume_embeddings (resume_id uuid primary key references public.candidate_resumes(id) on delete cascade, embedding vector(384) not null, updated_at timestamptz not null default now());
create table if not exists public.job_analysis_snapshots (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, created_by uuid references auth.users(id) on delete set null, note text, created_at timestamptz not null default now());
create table if not exists public.job_snapshot_candidates (id uuid primary key default gen_random_uuid(), snapshot_id uuid not null references public.job_analysis_snapshots(id) on delete cascade, candidate_resume_id uuid references public.candidate_resumes(id) on delete set null, candidate_id uuid references public.candidates(id) on delete set null, final_score numeric(8,5), raw_score numeric(8,5), penalty numeric(8,5), warnings jsonb, breakdown jsonb, created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text, body text, type text, message text, meta jsonb, created_at timestamptz not null default now(), read_at timestamptz);
create trigger trg_companies_updated before update on public.companies for each row execute function public.set_updated_at();
create trigger trg_profiles_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger trg_candidates_updated before update on public.candidates for each row execute function public.set_updated_at();
create trigger trg_jobs_updated before update on public.jobs for each row execute function public.set_updated_at();
create trigger trg_job_requirements_updated before update on public.job_requirements for each row execute function public.set_updated_at();
create trigger trg_candidate_resumes_updated before update on public.candidate_resumes for each row execute function public.set_updated_at();
create or replace function public.current_profile_company_id() returns uuid language sql stable as $$ select company_id from public.profiles where id = auth.uid() $$;
create or replace function public.bootstrap_company(p_name text) returns uuid language plpgsql security definer set search_path = public as $$ declare v_company_id uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; insert into public.companies(name, created_by) values (trim(p_name), auth.uid()) returning id into v_company_id; insert into public.profiles(id, company_id, role) values (auth.uid(), v_company_id, 'admin') on conflict (id) do update set company_id = excluded.company_id, role = 'admin'; return v_company_id; end; $$;
grant execute on function public.bootstrap_company(text) to authenticated;
create or replace function public.apply_to_job(p_job_id uuid) returns uuid language plpgsql security definer set search_path = public as $$ declare v_job public.jobs%rowtype; v_profile public.profiles%rowtype; v_candidate_id uuid; v_candidate_resume_id uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; select * into v_job from public.jobs where id = p_job_id and status = 'open'; if v_job.id is null then raise exception 'Job not found or not open'; end if; select * into v_profile from public.profiles where id = auth.uid(); select id into v_candidate_id from public.candidates where company_id = v_job.company_id and user_id = auth.uid() limit 1; if v_candidate_id is null then insert into public.candidates(company_id, user_id, full_name, phone, created_by) values (v_job.company_id, auth.uid(), coalesce(nullif(v_profile.full_name, ''), split_part(coalesce((auth.jwt() ->> 'email'), 'Applicant'), '@', 1)), v_profile.phone, auth.uid()) returning id into v_candidate_id; end if; select id into v_candidate_resume_id from public.candidate_resumes where job_id = p_job_id and candidate_id = v_candidate_id order by created_at desc limit 1; if v_candidate_resume_id is null then insert into public.candidate_resumes(company_id, job_id, candidate_id, status, stage) values (v_job.company_id, p_job_id, v_candidate_id, 'queued', 'submitted') returning id into v_candidate_resume_id; end if; insert into public.notifications(user_id, title, body, type, meta) values (auth.uid(),'تم إنشاء طلب التقديم','يمكنك الآن رفع السيرة الذاتية وسيبدأ التحليل تلقائيًا.','application_created', jsonb_build_object('application_id', v_candidate_resume_id, 'job_id', p_job_id)); return v_candidate_resume_id; end; $$;
grant execute on function public.apply_to_job(uuid) to authenticated;
create or replace function public.whoami() returns table(user_id uuid, company_id uuid, role text) language sql security definer set search_path = public as $$ select auth.uid(), p.company_id, p.role from public.profiles p where p.id = auth.uid() $$;
grant execute on function public.whoami() to authenticated;
create or replace function public.compute_similarity_candidate(p_job_id uuid, p_candidate_resume_id uuid) returns table(distance real, similarity real) language sql security definer set search_path = public as $$ select (je.embedding <=> ce.embedding)::real as distance, greatest(0::real, least(1::real, (1 - (je.embedding <=> ce.embedding))::real)) as similarity from public.job_embeddings je join public.candidate_resume_embeddings ce on ce.resume_id = p_candidate_resume_id where je.job_id = p_job_id $$;
grant execute on function public.compute_similarity_candidate(uuid, uuid) to authenticated;
create or replace function public.purge_expired_resume_data() returns integer language plpgsql security definer set search_path = public as $$ declare v_deleted integer := 0; begin update public.candidate_resumes set text_extracted = null, parsed_json = null, last_error = null where retention_until < now() and (text_extracted is not null or parsed_json is not null or last_error is not null); get diagnostics v_deleted = row_count; return v_deleted; end; $$;
alter table public.companies enable row level security; alter table public.profiles enable row level security; alter table public.candidates enable row level security; alter table public.jobs enable row level security; alter table public.job_requirements enable row level security; alter table public.candidate_resumes enable row level security; alter table public.candidate_scores enable row level security; alter table public.job_analysis_snapshots enable row level security; alter table public.job_snapshot_candidates enable row level security; alter table public.notifications enable row level security;
create policy profiles_self_read on public.profiles for select using (id = auth.uid());
create policy profiles_self_write on public.profiles for insert with check (id = auth.uid());
create policy profiles_self_update on public.profiles for update using (id = auth.uid());
create policy companies_member_read on public.companies for select using (id = public.current_profile_company_id());
create policy jobs_public_open_read on public.jobs for select using (status = 'open');
create policy jobs_company_manage on public.jobs for all using (company_id = public.current_profile_company_id()) with check (company_id = public.current_profile_company_id());
create policy requirements_company_read on public.job_requirements for select using (exists (select 1 from public.jobs j where j.id = job_id and (j.status = 'open' or j.company_id = public.current_profile_company_id())));
create policy requirements_company_write on public.job_requirements for all using (exists (select 1 from public.jobs j where j.id = job_id and j.company_id = public.current_profile_company_id())) with check (exists (select 1 from public.jobs j where j.id = job_id and j.company_id = public.current_profile_company_id()));
create policy candidates_company_read on public.candidates for select using (company_id = public.current_profile_company_id() or user_id = auth.uid());
create policy candidates_company_write on public.candidates for all using (company_id = public.current_profile_company_id() or user_id = auth.uid()) with check (company_id = public.current_profile_company_id() or user_id = auth.uid());
create policy resumes_company_or_owner_read on public.candidate_resumes for select using (company_id = public.current_profile_company_id() or exists (select 1 from public.candidates c where c.id = candidate_id and c.user_id = auth.uid()));
create policy resumes_company_or_owner_write on public.candidate_resumes for all using (company_id = public.current_profile_company_id() or exists (select 1 from public.candidates c where c.id = candidate_id and c.user_id = auth.uid())) with check (company_id = public.current_profile_company_id() or exists (select 1 from public.candidates c where c.id = candidate_id and c.user_id = auth.uid()));
create policy scores_company_or_owner_read on public.candidate_scores for select using (exists (select 1 from public.candidate_resumes cr join public.candidates c on c.id = cr.candidate_id where cr.id = candidate_resume_id and (cr.company_id = public.current_profile_company_id() or c.user_id = auth.uid())));
create policy notifications_self on public.notifications for select using (user_id = auth.uid());
create policy snapshots_company on public.job_analysis_snapshots for all using (company_id = public.current_profile_company_id()) with check (company_id = public.current_profile_company_id());
create policy snapshot_items_company on public.job_snapshot_candidates for select using (exists (select 1 from public.job_analysis_snapshots s where s.id = snapshot_id and s.company_id = public.current_profile_company_id()));
insert into storage.buckets (id, name, public) values ('resumes', 'resumes', false) on conflict (id) do nothing;
create policy resumes_bucket_authenticated_read on storage.objects for select to authenticated using (bucket_id = 'resumes');
create policy resumes_bucket_authenticated_write on storage.objects for insert to authenticated with check (bucket_id = 'resumes');
create policy resumes_bucket_authenticated_update on storage.objects for update to authenticated using (bucket_id = 'resumes') with check (bucket_id = 'resumes');
